/// what was last sent: the bytes of each of the game's own fields and of each row, as the step's walk writes them
#[derive(Default)] pub struct PuppetMemo { pub top: Vec<Vec<u8>>, pub rows: Vec<Vec<Vec<u8>>>, pub top_cut: Vec<Vec<u32>>, pub row_cut: Vec<Vec<Vec<u32>>>, pub all: bool }

const PARTS: usize = 357; const TABLES: usize = 56;
#[inline] fn part(out: &mut W, t: &mut W, was: &mut Vec<u8>, all: bool) { if (all && !t.b.is_empty()) || *was != t.b { out.b.push(1); out.b.extend_from_slice(&t.b); keep(was, t); } else { out.b.push(0); } t.b.clear(); }
/// a row or a part that differs: a bit a leaf, then the bytes of the leaves that differ from what was last sent
#[inline] fn cut(out: &mut W, t: &[u8], now: &[u32], was: &[u8], wc: &[u32], all: bool) { let n = now.len(); let at = out.b.len(); out.b.resize(at + (n + 7) / 8, 0); let same_shape = wc.len() == n && !all; let (mut a0, mut b0) = (0usize, 0usize); for k in 0..n { let b1 = now[k] as usize; let a1 = if same_shape { wc[k] as usize } else { 0 }; if !same_shape || was[a0..a1] != t[b0..b1] { out.b[at + k / 8] |= 1 << (k % 8); out.b.extend_from_slice(&t[b0..b1]); } a0 = a1; b0 = b1; } }
#[inline] fn keep_cut(was: &mut Vec<u32>, now: &[u32]) { was.clear(); was.extend_from_slice(now); }
#[inline] fn part_cut(out: &mut W, t: &mut W, c: &mut Vec<u32>, was: &mut Vec<u8>, wc: &mut Vec<u32>, all: bool) { if (all && !t.b.is_empty()) || *was != t.b { out.b.push(1); cut(out, &t.b, c, was, wc, all); keep(was, t); keep_cut(wc, c); } else { out.b.push(0); } t.b.clear(); c.clear(); }
/// the row as last sent: copied, not swapped, so each row keeps the room of its own bytes and not the scratch's (a snow field's part passed its capacity to every row, and the module to 2 GB)
#[inline] fn keep(was: &mut Vec<u8>, t: &W) { was.clear(); was.extend_from_slice(&t.b); was.shrink_to(t.b.len() * 2); }

